(()=>{if(window.__hsjReminderOnMapV12)return;window.__hsjReminderOnMapV12=true;
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
const fmt=v=>{const m=String(v||'').slice(0,10).match(/^(\d{4})-(\d\d)-(\d\d)$/);return m?m[3]+'/'+m[2]+'/'+m[1]:v||'—'};
const number=x=>{let n=String(x?.phone||'').replace(/\D/g,'');if(n.startsWith('55')&&[12,13].includes(n.length))n=n.slice(2);return [10,11].includes(n.length)?'55'+n:null};
async function reminder(id){const x=S.rows.find(r=>r.id===id);if(!x)return alert('Paciente não encontrado');if(x.stage!=='mapa_cirurgico')return alert('Paciente ainda não está no Mapa Cirúrgico.');try{const rows=await api('/rest/v1/surgery_appointment_details?surgery_id=eq.'+encodeURIComponent(id)+'&select=*');const a=rows?.[0];if(!a)return alert('Agendamento não localizado; confirme os dados antes de enviar.');const n=number(x);if(!n)return alert('WhatsApp inválido. Atualize o telefone do paciente com DDD.');const msg='Olá, '+x.patient_name+'!\nAqui é do Setor de Marcação de Cirurgia do Hospital São José.\n\nConfirmamos seu agendamento cirúrgico:\nProcedimento: '+(x.procedure_name||'')+'\nData: '+fmt(a.scheduled_date)+'\nHorário da cirurgia: '+String(a.scheduled_time||'').slice(0,5)+'\nChegada: '+(a.arrival_time?String(a.arrival_time).slice(0,5):'Conforme orientação da equipe')+'\nLocal: '+a.location+'\n\nOrientações: '+a.instructions+'\n\nResponsável pelo agendamento: '+a.scheduled_by_name+'\nPor favor, confirme o recebimento.';window.open('https://wa.me/'+n+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer');}catch(e){alert('Falha ao preparar lembrete: '+e.message)}}
window.hsjMapReminderV12=reminder;
const oldMap=window.renderMap;
window.renderMap=function(){const r=oldMap.apply(this,arguments);const content=document.getElementById('content');if(!content)return r;const actions=[...content.querySelectorAll('button[onclick*="editMapPatient("]')];for(const b of actions){const id=(b.getAttribute('onclick')||'').match(/'([0-9a-f-]{36})'/)?.[1];if(!id||b.parentElement.querySelector('[data-hsj-map-reminder]'))continue;const btn=document.createElement('button');btn.className='btn small green';btn.dataset.hsjMapReminder='1';btn.textContent='WhatsApp — lembrete de cirurgia';btn.onclick=()=>window.hsjMapReminderV12(id);b.after(btn)}return r};
const originalOpen=window.hsjAgendaSurgery;
window.hsjAgendaSurgery=async function(id){await originalOpen(id);const buttons=[...document.querySelectorAll('#modal .mf button')];buttons.forEach(b=>{if(/WhatsApp — contato efetivo/i.test(b.textContent))b.remove();if(/Salvar triagem e agendar/i.test(b.textContent))b.textContent='Salvar triagem e encaminhar ao Mapa Cirúrgico';});};
const priorSave=window.hsjConcluirTriagemMapa;
window.hsjConcluirTriagemMapa=async function(id){const oldOpen=window.open;try{window.open=function(url,...args){if(url==='about:blank')return null;return oldOpen.call(window,url,...args)};return await priorSave(id)}finally{window.open=oldOpen}};
window.hsjFinishSurgeryWithWhatsApp=window.hsjConcluirTriagemMapa;
window.hsjConfirmSurgeryAndMap=window.hsjConcluirTriagemMapa;
})();